def _glom_match(target, spec, scope):
    if isinstance(spec, type):
        if not isinstance(target, spec):
            raise TypeMatchError(type(target), spec)
        return target
    if hasattr(spec, 'glomit'):
        return scope[glom](target, spec, scope)
    if isinstance(spec, dict):
        return _handle_dict(target, spec, scope)
    if isinstance(spec, (list, tuple, set, frozenset)):
        if not isinstance(target, type(spec)):
            raise TypeMatchError(type(target), type(spec))
        if type(spec) in (set, frozenset):
            if not spec:
                if target:
                    raise MatchError("{0!r} does not match {1!r}", target, spec)
                return target
            if len(spec) != 1:
                raise MatchError("set/frozenset specs must have exactly one element")
            (item_spec,) = spec
            for item in target:
                scope[glom](item, item_spec, scope)
            return target
        if type(spec) is list:
            if not spec:
                if target:
                    raise MatchError("{0!r} does not match {1!r}", target, spec)
                return target
            if len(spec) != 1:
                raise MatchError("list specs must have exactly one element")
            (item_spec,) = spec
            result = []
            for item in target:
                result.append(scope[glom](item, item_spec, scope))
            return result
        if type(spec) is tuple:
            if len(spec) != len(target):
                raise MatchError("{0!r} does not match {1!r}", target, spec)
            result = []
            for item, item_spec in zip(target, spec):
                result.append(scope[glom](item, item_spec, scope))
            return type(target)(result)
    if callable(spec):
        try:
            if not spec(target):
                raise MatchError("{0!r} did not match {1!r}", target, spec)
        except MatchError:
            raise
        except Exception as e:
            raise MatchError("{0!r} did not match {1!r}: {2!r}", target, spec, e)
        return target
    if target != spec:
        raise MatchError("{0!r} does not match {1!r}", target, spec)
    return target
